(()=>{'use strict';let catalog=null,selected=null;const $=id=>document.getElementById(id);function log(x){$('log').textContent+=`\n${new Date().toLocaleTimeString()} ${x}`}function render(){const q=$('search').value.toLowerCase();const pf=$('platform').value;const ff=$('format').value;const items=catalog.applications.filter(a=>(!q||a.title.toLowerCase().includes(q)||a.id.includes(q))&&(!pf||a.platforms.includes(pf))&&(!ff||a.formats.includes(ff)));$('available').innerHTML=items.map(a=>`<article class="card" data-id="${a.id}"><b>${a.title}</b><small>${a.category}</small><div>${a.platforms.map(x=>`<span class="tag">${x}</span>`).join('')}</div><div>${a.formats.map(x=>`<span class="tag">${x}</span>`).join('')}</div></article>`).join('')||'<p>No matching applications.</p>';if(selected)show(selected)}function show(a){selected=a;$('details').innerHTML=`<h3>${a.title}</h3><p>ID: ${a.id}</p><p>Platforms: ${a.platforms.join(', ')}</p><p>Formats: ${a.formats.join(', ')}</p><p>Mode: ${a.default_mode}</p>`}async function request(action){if(!selected)return log('Select an application first.');const body={action,app_id:selected.id,mode:action==='dry-run'?'dry-run':selected.default_mode};try{const r=await fetch('/api/installer',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});if(!r.ok)throw Error(`backend unavailable (${r.status})`);const x=await r.json();log(JSON.stringify(x));$('backend-state').textContent=x.backend||'Native backend';}catch(e){if(action==='dry-run'){log(`Dry run: ${selected.title} (${selected.formats.join(', ')})`)}else{log(`${action}: native backend unavailable; no host operation was executed.`);request('dry-run')}}}async function load(){const r=await fetch('installer_catalog.json',{cache:'no-store'});catalog=await r.json();$('format').innerHTML='<option value="">All package formats</option>'+catalog.package_formats.map(x=>`<option value="${x.id}">${x.id}</option>`).join('');render()}document.addEventListener('click',e=>{const c=e.target.closest('.card');if(c)show(catalog.applications.find(a=>a.id===c.dataset.id));});['search','platform','format'].forEach(id=>$(id).addEventListener('input',render));$('refresh').onclick=load;$('install').onclick=()=>request('install');$('dry-run').onclick=()=>request('dry-run');$('remove').onclick=()=>request('remove');$('update').onclick=()=>request('update');window.ChimeraInstallerManager={refresh:load,install:()=>request('install'),remove:()=>request('remove'),update:()=>request('update'),dryRun:()=>request('dry-run')};load().catch(e=>log('Catalog load failed: '+e.message));})();
